create extension if not exists pgcrypto;
create table if not exists public.conjuntos(id uuid primary key default gen_random_uuid(),nombre text not null,ciudad text,estado text default 'activo',created_at timestamptz default now());
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,nombre text not null,rol text not null default 'vigilante' check(rol in ('admin','vigilante')),conjunto_id uuid not null references public.conjuntos(id),conjunto_nombre text,estado text default 'activo');
create table if not exists public.vehicles(id uuid primary key default gen_random_uuid(),conjunto_id uuid not null references public.conjuntos(id),apto text not null,residente text not null,placa text not null,marca_modelo text,color text,chip_uid text not null,estado text default 'activo' check(estado in ('activo','bloqueado')),created_at timestamptz default now(),unique(conjunto_id,chip_uid),unique(conjunto_id,placa));
create table if not exists public.access_logs(id uuid primary key default gen_random_uuid(),conjunto_id uuid references public.conjuntos(id),fecha_hora timestamptz default now(),chip_uid text not null,vehicle_id uuid references public.vehicles(id),usuario_id uuid references public.profiles(id),placa text,apto text,residente text,resultado text not null check(resultado in ('AUTORIZADO','DENEGADO')),sentido text not null check(sentido in ('entrada','salida')),observacion text);
insert into public.conjuntos(nombre,ciudad) select 'Terragrata','Dosquebradas, Risaralda' where not exists(select 1 from public.conjuntos where nombre='Terragrata');
alter table public.conjuntos enable row level security;alter table public.profiles enable row level security;alter table public.vehicles enable row level security;alter table public.access_logs enable row level security;
revoke all on public.conjuntos,public.profiles,public.vehicles,public.access_logs from anon;grant select,insert,update,delete on public.conjuntos,public.profiles,public.vehicles,public.access_logs to authenticated;
create or replace function public.my_conjunto_id() returns uuid language sql stable security definer set search_path=public as $$select conjunto_id from public.profiles where id=auth.uid() and estado='activo' limit 1$$;
create or replace function public.my_role() returns text language sql stable security definer set search_path=public as $$select rol from public.profiles where id=auth.uid() and estado='activo' limit 1$$;
drop policy if exists p1 on public.conjuntos;create policy p1 on public.conjuntos for select to authenticated using(id=public.my_conjunto_id());
drop policy if exists p2 on public.profiles;create policy p2 on public.profiles for select to authenticated using(conjunto_id=public.my_conjunto_id());
drop policy if exists p3 on public.vehicles;create policy p3 on public.vehicles for select to authenticated using(conjunto_id=public.my_conjunto_id());
drop policy if exists p4 on public.vehicles;create policy p4 on public.vehicles for insert to authenticated with check(conjunto_id=public.my_conjunto_id() and public.my_role()='admin');
drop policy if exists p5 on public.vehicles;create policy p5 on public.vehicles for update to authenticated using(conjunto_id=public.my_conjunto_id() and public.my_role()='admin') with check(conjunto_id=public.my_conjunto_id() and public.my_role()='admin');
drop policy if exists p6 on public.vehicles;create policy p6 on public.vehicles for delete to authenticated using(conjunto_id=public.my_conjunto_id() and public.my_role()='admin');
drop policy if exists p7 on public.access_logs;create policy p7 on public.access_logs for select to authenticated using(conjunto_id=public.my_conjunto_id());
drop policy if exists p8 on public.access_logs;create policy p8 on public.access_logs for insert to authenticated with check(conjunto_id=public.my_conjunto_id() and usuario_id=auth.uid());
create or replace function public.registrar_acceso(p_chip_uid text,p_sentido text default 'entrada') returns json language plpgsql security definer set search_path=public as $$declare v public.vehicles%rowtype;r text;begin select * into v from public.vehicles where conjunto_id=public.my_conjunto_id() and upper(chip_uid)=upper(trim(p_chip_uid)) limit 1;r:=case when v.id is not null and v.estado='activo' then 'AUTORIZADO' else 'DENEGADO' end;insert into public.access_logs(conjunto_id,chip_uid,vehicle_id,usuario_id,placa,apto,residente,resultado,sentido)values(public.my_conjunto_id(),upper(trim(p_chip_uid)),v.id,auth.uid(),v.placa,v.apto,v.residente,r,p_sentido);return json_build_object('resultado',r,'placa',v.placa,'apto',v.apto,'residente',v.residente,'marca_modelo',v.marca_modelo,'color',v.color);end$$;
grant execute on function public.registrar_acceso(text,text) to authenticated;